<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Services\Dezerx\DiscordBot\ConsoleLog; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\TailConsoleRequest; class ConsoleTailController extends ClientApiController { public function __construct(private ConsoleLog $console) { parent::__construct(); } public function __invoke(TailConsoleRequest $request, Server $server): JsonResponse { $tail = $this->console->tail($server, (int) $request->input('lines', 25)); if ($tail === null) { return new JsonResponse([ 'errors' => [['code' => 'ConsoleUnavailable', 'status' => '502', 'detail' => 'The node did not hand back the console.']], ], 502); } return new JsonResponse(['object' => 'console_tail', 'data' => $tail]); } } 